<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Holder\RelyingPartyCodeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the RelyingPartyCodeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class RelyingPartyCodeAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getCode returns null on a freshly created holder.
     */
    public function testCodeNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithRelyingPartyCodeAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isCodeAssigned());
        $this->assertNull($holder->getCode());
    }
}
class ImplWithRelyingPartyCodeAttributeHolderUnitTest
{
    use RelyingPartyCodeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedCodeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultCode();
    }
}
